#include <iostream>
using namespace std;

class Stack {
private:
    int arr[4];
    int top;
public:
    Stack() {
        top = -1;
    }
    bool isEmpty() {
        return top < 0;
    }
    bool isFull() {
        return top == 3;
    }
    void push(int value) {
        if (isFull()) {
            cout << "Stack overflow: " << value << " does not fit" << endl;
            return;
        }
        arr[++top] = value;
    }
    int pop() {
        if (isEmpty()) {
            cout << "Stack is empty" << endl;
            return -1;
        }
        return arr[top--];
    }
};

int main() {
    Stack s;
    s.push(10);
    s.push(20);
    s.push(30);
    s.push(40);
    s.push(50);
    cout << "Popped " << s.pop() << endl;
    cout << "Popped " << s.pop() << endl;
    return 0;
}
